parameters.query:
SELECT DISTINCT ON (workflow_name, stage_name) workflow_name, stage_name, status, started_at, finished_at,
       duration_ms, retry_count, error_message, warning_count, error_count
FROM trading.pipeline_runs ORDER BY workflow_name, stage_name, started_at DESC;

