function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function esc(s) {
  return safeStr(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function num(v) {
  const n = Number(v);
  return isNaN(n) ? null : n;
}
function rows(nodeName) {
  // alwaysOutputData auf den Quell-Nodes verhindert, dass eine 0-Zeilen-Abfrage die
  // Merge-Kette abbricht (combineAll = Kreuzprodukt, 0 auf einer Seite = 0 gesamt) -
  // erzeugt dabei aber ein leeres Platzhalter-Item, das hier herausgefiltert wird.
  try { return $(nodeName).all().map(i => i.json || {}).filter(j => j && Object.keys(j).length > 0); } catch (e) { return []; }
}

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}
const heute = getBusinessDate();
const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const fundamentaldaten = rows('DB: Fundamentaldaten laden');
const marktKontext     = rows('DB: Marktumfeld laden');
const techSignale      = rows('DB: Technische Signale laden');
const news             = rows('DB: News laden (trading.*)').map(r => ({ datum_iso: r.published_at || r.created_at, relevanz: r.wirkung_staerke === 'hoch' ? 'hoch' : (r.wirkung_staerke === 'mittel' ? 'mittel' : '') }));
const empfehlungen     = rows('DB: Empfehlungen laden');
const vetosHeute       = rows('DB: Vetos heute (Uebersicht)');
const sitzungsstatus    = rows('DB: Sitzungsstatus (Uebersicht)');
const strategieSignale  = rows('DB: Strategiesignale heute (Uebersicht)');
const marktregime       = rows('DB: Marktregime (Uebersicht)');
const scanKandidaten    = rows('DB: Scan-Kandidaten letzter Lauf (Uebersicht)');
const offenePaperTrades = rows('DB: Offene Paper Trades (Uebersicht)');
const geschlossenePaperTrades = rows('DB: Geschlossene Paper Trades (Uebersicht)');
const strategieauswertung = rows('DB: Strategieauswertung (Uebersicht)');
const portfolioChecks = rows('DB: Portfoliorisiko aktuell (Uebersicht)');
const stressSzenarien = rows('DB: Stressszenarien aktuell (Uebersicht)');
const lernstatus = rows('DB: Lernstatus (Uebersicht)');
const kursHistorie     = rows('DB: Kursverlauf laden');

// Paket 9: Mehrtages-Trend aus Paket 8s Historie-Tabellen (letzte 5 Handelstage).
const trendSignaleRows = rows('DB: Trend-Signale laden');
const trendSignaleByTicker = {};
for (const r of trendSignaleRows) {
  const k = safeStr(r.ticker);
  if (!k) continue;
  if (!trendSignaleByTicker[k]) trendSignaleByTicker[k] = [];
  trendSignaleByTicker[k].push(r);
}
for (const k of Object.keys(trendSignaleByTicker)) trendSignaleByTicker[k].sort((a, b) => safeStr(a.snapshot_date).localeCompare(safeStr(b.snapshot_date)));

function trendPfeil(ticker) {
  const arr = trendSignaleByTicker[safeStr(ticker)] || [];
  if (arr.length < 2) return '<span class="hint" style="margin:0">zu wenig Historie</span>';
  const erstRsi = num(arr[0].rsi);
  const letztRsi = num(arr[arr.length - 1].rsi);
  if (erstRsi === null || letztRsi === null) return '–';
  if (letztRsi > erstRsi + 1) return '↑ steigend';
  if (letztRsi < erstRsi - 1) return '↓ fallend';
  return '→ seitwaerts';
}

function letzterStand(list, getFeld) {
  const daten = list.map(r => safeStr(getFeld(r))).filter(Boolean).sort();
  return daten.length > 0 ? daten[daten.length - 1] : null;
}

function quelleZeile(name, list, getFeld) {
  const stand = letzterStand(list, getFeld);
  const standDatum = stand ? stand.substring(0, 10) : null;
  const aktuell = standDatum === heute;
  const badge = list.length === 0
    ? '<span class="badge warn">leer</span>'
    : aktuell
      ? '<span class="badge ok">aktuell</span>'
      : '<span class="badge warn">veraltet (' + esc(standDatum || 'unbekannt') + ')</span>';
  return '<tr><td>' + esc(name) + '</td><td class="num">' + list.length + '</td><td>' + (stand ? esc(stand) : '—') + '</td><td>' + badge + '</td></tr>';
}

const quellenHtml =
  quelleZeile('stock_fundamentals', fundamentaldaten, r => r.datum) +
  quelleZeile('stock_market_context', marktKontext, r => r.datum) +
  quelleZeile('stock_technical_signals', techSignale, r => r.datum) +
  quelleZeile('stock_news_evaluated', news, r => r.datum_iso || r.datum) +
  quelleZeile('stock_empfehlungen', empfehlungen, r => r.letzte_aktualisierung) +
  quelleZeile('stock_price_history', kursHistorie, r => r.datum);

// Technische Signale heute
const techHeute = techSignale.filter(s => safeStr(s.datum).startsWith(heute));
const handelskandidaten = techHeute.filter(s => s.handels_status === 'handelskandidat');
const beobachten = techHeute.filter(s => s.handels_status === 'beobachten');

function signalZeile(s) {
  return '<tr><td>' + esc(s.ticker) + '</td><td>' + esc(s.name) + '</td><td>' + esc(s.handels_status_text || s.handels_status) + '</td>' +
    '<td class="num">' + esc(s.rsi) + '</td><td>' + esc(s.macd_signal) + '</td><td>' + esc(s.richtung) + '</td>' +
    '<td>' + trendPfeil(s.ticker) + '</td></tr>';
}
const kandidatenHtml = handelskandidaten.length > 0 ? handelskandidaten.map(signalZeile).join('') : '<tr><td colspan="6" class="empty">keine heute</td></tr>';
const beobachtenHtml = beobachten.length > 0 ? beobachten.map(signalZeile).join('') : '<tr><td colspan="6" class="empty">keine heute</td></tr>';

// Empfehlungs-Watchlist
const offen = empfehlungen.filter(e => e.status === 'offen');
const geschlossen = empfehlungen.filter(e => e.status === 'geschlossen');
const perfWerte = geschlossen.map(e => num(e.performance_pct)).filter(v => v !== null);
const avgPerf = perfWerte.length > 0 ? (perfWerte.reduce((a, b) => a + b, 0) / perfWerte.length).toFixed(2) : null;
const hitRate = perfWerte.length > 0 ? Math.round((perfWerte.filter(v => v > 0).length / perfWerte.length) * 100) : null;

function empfehlungZeile(e) {
  const rrr = num(e.reward_risk_ratio);
  const ablauf = e.thesis_expires_at ? new Date(e.thesis_expires_at).toLocaleDateString('de-DE') : '—';
  const abgelaufen = e.thesis_expires_at && new Date(e.thesis_expires_at).getTime() < Date.now();
  const entryZone = (e.entry_zone_low != null && e.entry_zone_high != null) ? (esc(e.entry_zone_low) + '–' + esc(e.entry_zone_high)) : '—';
  return '<tr><td>' + esc(e.ticker) + '</td><td>' + esc(e.richtung) + '</td><td>' + esc(e.entry_datum) + '</td>' +
    '<td class="num">' + esc(e.entry_kurs) + '</td><td>' + esc(e.status) + '</td>' +
    '<td class="num">' + esc(e.stop_price) + '</td><td class="num">' + esc(e.target_price) + '</td>' +
    '<td class="num">' + (rrr !== null ? rrr.toFixed(2) : '—') + '</td>' +
    '<td class="num">' + esc(e.max_planned_loss) + '</td>' +
    '<td class="num">' + esc(e.theoretical_quantity) + '</td>' +
    '<td>' + esc(e.strategy) + '</td>' +
    '<td class="' + (abgelaufen ? 'bad' : '') + '">' + esc(ablauf) + '</td>' +
    '<td class="num">' + esc(e.opportunity_score) + '</td><td class="num">' + esc(e.risk_score) + '</td><td class="num">' + esc(e.evidence_confidence) + '</td>' +
    '<td>' + entryZone + '</td><td>' + esc(e.combined_regime) + '</td></tr>';
}
const offenHtml = offen.length > 0 ? offen.map(empfehlungZeile).join('') : '<tr><td colspan="11" class="empty">keine offenen Positionen</td></tr>';

// Welle 1, AP5: harte Vetos heute (aus trading.recommendation_veto_log)
function vetoZeile(v) {
  let blockers = [];
  try { blockers = typeof v.blockers_json === 'string' ? JSON.parse(v.blockers_json) : (v.blockers_json || []); } catch (e) {}
  const codes = blockers.map(b => b.code).join(', ');
  const zeit = v.created_at ? new Date(v.created_at).toLocaleTimeString('de-DE') : '';
  return '<tr><td>' + esc(v.ticker) + '</td><td>' + esc(v.action) + '</td><td>' + esc(codes) + '</td><td>' + esc(zeit) + '</td></tr>';
}
const vetosHtml = vetosHeute.length > 0 ? vetosHeute.map(vetoZeile).join('') : '<tr><td colspan="4" class="empty">keine harten Vetos heute</td></tr>';

// Welle 1, AP4: Boersensitzungs-Status je aktivem Ticker
function sessionBadgeClass(s) {
  if (s === 'closed_complete') return 'ok';
  if (s === 'open_intraday' || s === 'stale') return 'warn';
  return '';
}
function sessionZeile(s) {
  return '<tr><td>' + esc(s.ticker) + '</td><td>' + esc(s.market_code) + '</td>' +
    '<td><span class="badge ' + sessionBadgeClass(s.session_status) + '">' + esc(s.session_status) + '</span></td>' +
    '<td>' + esc(s.letztes_verfuegbares_handelsdatum) + '</td></tr>';
}
const sessionHtml = sitzungsstatus.length > 0 ? sitzungsstatus.map(sessionZeile).join('') : '<tr><td colspan="4" class="empty">keine Daten</td></tr>';

// News heute
const newsHeute = news.filter(n => safeStr(n.datum_iso || n.datum).startsWith(heute));
const newsHoch = newsHeute.filter(n => n.relevanz === 'hoch').length;
const newsMittel = newsHeute.filter(n => n.relevanz === 'mittel').length;

